// AscendC RFFT1D kernel — computes 1D real FFT via DFT matrix-vector product
// The DFT coefficient matrix is pre-computed on host and passed as an interleaved
// real/imag weight tensor (2D: output_total × n_fft).  Each row produces one
// output element: real or imag at the correct interleaved position.
//
// Supports float32 only (reference model always casts to float32).

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_K = 16;    // output rows per tile
constexpr int32_t TILE_N = 512;   // input (n_fft) elements per tile

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

// GM->UB load with optional padding
__aicore__ inline void LoadGmToUbFloat(
    AscendC::LocalTensor<float> &dst,
    const AscendC::GlobalTensor<float> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<float> padParams{true, 0, 0, 0.0f};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

// UB->GM store
__aicore__ inline void StoreUbToGmFloat(
    AscendC::GlobalTensor<float> &dst,
    AscendC::LocalTensor<float> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

