// RFFT1D Kernel class
// =========================================================================

class Rfft1DKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x_in,
        GM_ADDR dft_weights,
        GM_ADDR y_out,
        int32_t batchSize,
        int32_t inputLen,
        int32_t nFft,
        int32_t outputTotal,
        float normScale)
    {
        batchSize_ = batchSize;
        inputLen_ = inputLen;
        nFft_ = nFft;
        outputTotal_ = outputTotal;
        normScale_ = normScale;

        uint64_t xStride = static_cast<uint64_t>(nFft_);
        uint64_t dftStride = static_cast<uint64_t>(nFft_);

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(x_in),
                             static_cast<uint64_t>(batchSize_) * xStride);
        dftGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(dft_weights),
                               static_cast<uint64_t>(outputTotal_) * dftStride);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y_out),
                             static_cast<uint64_t>(batchSize_) * outputTotal_);

        if (ASCEND_IS_AIV) {
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, TILE_N * sizeof(float));
            pipe.InitBuffer(dftInQueue_, BUFFER_NUM, TILE_K * TILE_N * sizeof(float));
            pipe.InitBuffer(prodBuf_, TILE_N * sizeof(float));
            pipe.InitBuffer(reduceBuf_, TILE_N * sizeof(float));
            pipe.InitBuffer(accumBuf_, TILE_K * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if (!ASCEND_IS_AIV) { return; }

        int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
        int32_t tasksPerCore = CeilDivI32(batchSize_, AscendC::GetBlockNum());

        for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
            int32_t bx = coreIdx * tasksPerCore + localIdx;
            if (bx >= batchSize_) { continue; }
            ProcessSequence(bx);
        }
    }

private:
    __aicore__ inline void CopyInX(int32_t bx, int32_t nStart, int32_t validN)
    {
        xLocal_ = xInQueue_.AllocTensor<float>();
        if (nStart < inputLen_) {
            int32_t copyLen = (nStart + validN <= inputLen_) ? validN : (inputLen_ - nStart);
            LoadGmToUbFloat(xLocal_, xGM_[static_cast<uint64_t>(bx) * nFft_ + nStart],
                            static_cast<uint32_t>(copyLen));
        }
        // Zeros beyond inputLen_ are handled by padParams in LoadGmToUbFloat
        // But we need to explicitly zero-pad the loaded region
        if (nStart + validN > inputLen_) {
            int32_t zeroStart = (nStart < inputLen_) ? (inputLen_ - nStart) : 0;
            if (zeroStart < validN) {
                AscendC::Duplicate<float>(xLocal_[zeroStart], 0.0f,
                                          static_cast<uint32_t>(validN - zeroStart));
            }
            if (nStart >= inputLen_) {
                AscendC::Duplicate<float>(xLocal_, 0.0f, static_cast<uint32_t>(validN));
            }
        }
        xInQueue_.EnQue(xLocal_);
    }

    __aicore__ inline void CopyInDft(int32_t rStart, int32_t validR, int32_t nStart, int32_t validN)
    {
        dftLocal_ = dftInQueue_.AllocTensor<float>();
        uint64_t dftOffset = static_cast<uint64_t>(rStart) * nFft_ + nStart;
        uint64_t dftStride = static_cast<uint64_t>(nFft_);
        // Load (validR, validN) tile from dftGM with row stride = nFft_
        // Since validR is small (<= TILE_K), we load one row at a time
        for (int32_t ri = 0; ri < validR; ++ri) {
            LoadGmToUbFloat(dftLocal_[ri * TILE_N],
                            dftGM_[static_cast<uint64_t>(rStart + ri) * nFft_ + nStart],
                            static_cast<uint32_t>(validN));
        }
        dftInQueue_.EnQue(dftLocal_);
    }

    __aicore__ inline float DotProduct(
        AscendC::LocalTensor<float> &xVec,
        AscendC::LocalTensor<float> &wVec,
        AscendC::LocalTensor<float> &prodVec,
        AscendC::LocalTensor<float> &reduceVec,
        int32_t count)
    {
        AscendC::Mul(prodVec, xVec, wVec, count);
        AscendC::ReduceSum<float>(reduceVec, prodVec, reduceVec, count);
        return reduceVec.GetValue(0);
    }

    __aicore__ inline void ProcessSequence(int32_t bx)
    {
        int32_t outputTotal = outputTotal_;

        // Process output rows in tiles of TILE_K
        for (int32_t rStart = 0; rStart < outputTotal; rStart += TILE_K) {
            int32_t validR = (rStart + TILE_K <= outputTotal) ? TILE_K : (outputTotal - rStart);

            // Initialize accumulators for this r tile
            accumLocal_ = accumBuf_.Get<float>();
            AscendC::Duplicate<float>(accumLocal_, 0.0f, static_cast<uint32_t>(validR));

            // Accumulate dot products across n tiles
            for (int32_t nStart = 0; nStart < nFft_; nStart += TILE_N) {
                int32_t validN = (nStart + TILE_N <= nFft_) ? TILE_N : (nFft_ - nStart);

                // Load input tile
                CopyInX(bx, nStart, validN);
                // Load DFT weight tile
                CopyInDft(rStart, validR, nStart, validN);

                // DeQue
                xLocal_ = xInQueue_.DeQue<float>();
                dftLocal_ = dftInQueue_.DeQue<float>();

                prodLocal_ = prodBuf_.Get<float>();
                reduceLocal_ = reduceBuf_.Get<float>();

                // Compute partial dot products for each output row
                for (int32_t ri = 0; ri < validR; ++ri) {
                    float part = DotProduct(xLocal_, dftLocal_[ri * TILE_N],
                                            prodLocal_, reduceLocal_, validN);
                    accumLocal_.SetValue(ri, accumLocal_.GetValue(ri) + part);
                }

                xInQueue_.FreeTensor(xLocal_);
                dftInQueue_.FreeTensor(dftLocal_);
            }

            // Apply norm scaling
            if (normScale_ != 1.0f) {
                AscendC::Muls(accumLocal_, accumLocal_, normScale_, validR);
            }

            // Store interleaved output
            // accumLocal_[ri] corresponds to output element rStart + ri
            // Write element by element
            for (int32_t ri = 0; ri < validR; ++ri) {
                int32_t r = rStart + ri;
                uint64_t yOffset = static_cast<uint64_t>(bx) * outputTotal_ + r;
                // Write single float via Duplicate + DataCopy
                AscendC::LocalTensor<float> tmp = prodBuf_.Get<float>();
                float val = accumLocal_.GetValue(ri);
                AscendC::Duplicate<float>(tmp, val, 1);
                AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
                AscendC::DataCopyPad(yGM_[yOffset], tmp, copyParams);
            }
        }
    }

private:
    int32_t batchSize_ = 0;
    int32_t inputLen_ = 0;
    int32_t nFft_ = 0;
    int32_t outputTotal_ = 0;
    float normScale_ = 1.0f;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<float> xGM_;
    AscendC::GlobalTensor<float> dftGM_;
    AscendC::GlobalTensor<float> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> dftInQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> prodBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accumBuf_;

    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> dftLocal_;
    AscendC::LocalTensor<float> prodLocal_;
    AscendC::LocalTensor<float> reduceLocal_;
    AscendC::LocalTensor<float> accumLocal_;
};

