// AscendC RFFT1D kernel — 1D Real-to-Complex FFT
//
// Approach: DFT via on-the-fly coefficient computation.
// Pre-computed `angles[n] = 2π·n / nFft` (nFft floats) on host.
// For each output position k (interleaved real/imag):
//   freq = k / 2
//   For each n_tile:
//     θ = freq * angles    (Muls)
//     c = cos(θ)  or -sin(θ)   (Cos / Sin + Muls)
//     dot += Σ(x * c)            (Mul + ReduceSum)
//   out[k] = dot * normScale
//
// Float32 only (reference model always casts to float32).

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_N = 1024;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

__aicore__ inline void LoadGmToUbFloat(
    AscendC::LocalTensor<float> &dst,
    const AscendC::GlobalTensor<float> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<float> padParams{true, 0, 0, 0.0f};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

__aicore__ inline void StoreUbToGmFloat(
    AscendC::GlobalTensor<float> &dst,
    AscendC::LocalTensor<float> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

