// RFFT1D Kernel
// =========================================================================

class Rfft1DKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR xPadded,
        GM_ADDR angles,
        GM_ADDR yOut,
        int32_t batchSize,
        int32_t inputLen,
        int32_t nFft,
        int32_t outputTotal,
        float normScale)
    {
        batchSize_ = batchSize;
        inputLen_ = inputLen;
        nFft_ = nFft;
        outputTotal_ = outputTotal;
        normScale_ = normScale;

        uint64_t xStride = static_cast<uint64_t>(nFft_);
        xPaddedGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(xPadded),
                                    static_cast<uint64_t>(batchSize_) * xStride);
        anglesGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(angles), nFft_);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(yOut),
                             static_cast<uint64_t>(batchSize_) * outputTotal_);

        if (ASCEND_IS_AIV) {
            const uint32_t tileBytes = TILE_N * sizeof(float);
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileBytes);
            pipe.InitBuffer(anglesInQueue_, BUFFER_NUM, tileBytes);
            pipe.InitBuffer(thetaBuf_, tileBytes);
            pipe.InitBuffer(coeffBuf_, tileBytes);
            pipe.InitBuffer(prodBuf_, tileBytes);
            pipe.InitBuffer(tmpBuf_, tileBytes);
        }
    }

    __aicore__ inline void Process()
    {
        if (!ASCEND_IS_AIV) { return; }

        int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
        int32_t tasksPerCore = CeilDivI32(batchSize_, AscendC::GetBlockNum());

        for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
            int32_t bx = coreIdx * tasksPerCore + localIdx;
            if (bx >= batchSize_) { continue; }
            ProcessSequence(bx);
        }
    }

private:
    // Load a tile of padded input
    __aicore__ inline void CopyInX(int32_t bx, int32_t nStart, int32_t validN)
    {
        xLocal_ = xInQueue_.AllocTensor<float>();
        if (nStart < inputLen_) {
            int32_t copyLen = (nStart + validN <= inputLen_) ? validN : (inputLen_ - nStart);
            LoadGmToUbFloat(xLocal_, xPaddedGM_[static_cast<uint64_t>(bx) * nFft_ + nStart],
                            static_cast<uint32_t>(copyLen));
        }
        // Zero-pad elements beyond inputLen_
        if (nStart + validN > inputLen_) {
            int32_t zeroStart = (nStart < inputLen_) ? (inputLen_ - nStart) : 0;
            if (zeroStart < validN) {
                AscendC::Duplicate<float>(xLocal_[zeroStart], 0.0f,
                                          static_cast<uint32_t>(validN - zeroStart));
            }
        }
        if (nStart >= inputLen_) {
            AscendC::Duplicate<float>(xLocal_, 0.0f, static_cast<uint32_t>(validN));
        }
        xInQueue_.EnQue(xLocal_);
    }

    // Load a tile of pre-computed angles
    __aicore__ inline void CopyInAngles(int32_t nStart, int32_t validN)
    {
        anglesLocal_ = anglesInQueue_.AllocTensor<float>();
        LoadGmToUbFloat(anglesLocal_, anglesGM_[nStart], static_cast<uint32_t>(validN));
        anglesInQueue_.EnQue(anglesLocal_);
    }

    // Compute one output element: dot product of input with DFT row
    __aicore__ inline float ComputeOutputElement(int32_t bx, int32_t k)
    {
        int32_t freq = k / 2;
        int32_t isReal = (k % 2 == 0) ? 1 : 0;
        float accum = 0.0f;

        thetaLocal_ = thetaBuf_.Get<float>();
        coeffLocal_ = coeffBuf_.Get<float>();
        prodLocal_ = prodBuf_.Get<float>();
        tmpLocal_ = tmpBuf_.Get<float>();

        for (int32_t nStart = 0; nStart < nFft_; nStart += TILE_N) {
            int32_t validN = (nStart + TILE_N <= nFft_) ? TILE_N : (nFft_ - nStart);

            CopyInX(bx, nStart, validN);
            CopyInAngles(nStart, validN);

            xLocal_ = xInQueue_.DeQue<float>();
            anglesLocal_ = anglesInQueue_.DeQue<float>();

            // theta = freq * angles[n]
            if (freq == 0) {
                AscendC::Duplicate<float>(thetaLocal_, 0.0f, static_cast<uint32_t>(validN));
            } else {
                float freqF = static_cast<float>(freq);
                AscendC::Muls(thetaLocal_, anglesLocal_, freqF, validN);
            }

            // coefficient = cos(theta) for real, -sin(theta) for imag
            if (isReal) {
                AscendC::Cos(coeffLocal_, thetaLocal_, validN);
            } else {
                AscendC::Sin(coeffLocal_, thetaLocal_, validN);
                AscendC::Muls(coeffLocal_, coeffLocal_, -1.0f, validN);
            }

            // prod = x * coefficient
            AscendC::Mul(prodLocal_, xLocal_, coeffLocal_, validN);

            // partial sum = Σ prod
            AscendC::ReduceSum<float>(tmpLocal_, prodLocal_, tmpLocal_,
                                      static_cast<uint32_t>(validN));
            accum += tmpLocal_.GetValue(0);

            xInQueue_.FreeTensor(xLocal_);
            anglesInQueue_.FreeTensor(anglesLocal_);
        }

        return accum * normScale_;
    }

    __aicore__ inline void ProcessSequence(int32_t bx)
    {
        for (int32_t k = 0; k < outputTotal_; ++k) {
            float val = ComputeOutputElement(bx, k);
            // Write to output
            AscendC::LocalTensor<float> tmpW = tmpBuf_.Get<float>();
            AscendC::Duplicate<float>(tmpW, val, 1);
            AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
            AscendC::DataCopyPad(yGM_[static_cast<uint64_t>(bx) * outputTotal_ + k], tmpW, copyParams);
        }
    }

private:
    int32_t batchSize_ = 0;
    int32_t inputLen_ = 0;
    int32_t nFft_ = 0;
    int32_t outputTotal_ = 0;
    float normScale_ = 1.0f;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<float> xPaddedGM_;
    AscendC::GlobalTensor<float> anglesGM_;
    AscendC::GlobalTensor<float> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> anglesInQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> thetaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> coeffBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> prodBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;

    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> anglesLocal_;
    AscendC::LocalTensor<float> thetaLocal_;
    AscendC::LocalTensor<float> coeffLocal_;
    AscendC::LocalTensor<float> prodLocal_;
    AscendC::LocalTensor<float> tmpLocal_;
};

// =========================================================================
// Kernel entry point
// =========================================================================

extern "C" __global__ __aicore__ void rfft1d(
    GM_ADDR xPadded,
    GM_ADDR angles,
    GM_ADDR yOut,
    int32_t batchSize,
    int32_t inputLen,
    int32_t nFft,
    int32_t outputTotal,
    float normScale)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);
    Rfft1DKernel kernel;
    kernel.Init(xPadded, angles, yOut, batchSize, inputLen, nFft, outputTotal, normScale);
    kernel.Process();
}
