// RFFT1D op_host — tiling calculation + angle pre-computation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cmath>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_rfft1d.h"

namespace ascend_kernel {

at::Tensor rfft1d(const at::Tensor &input, at::IntArrayRef n_arg, int64_t norm)
{
    // Input validation
    TORCH_CHECK(input.dtype() == at::kFloat, "RFFT1D kernel requires float32 input");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.numel() > 0, "input must have at least one element");

    int64_t inputLen = input.size(-1);
    int64_t nFft;
    if (n_arg.empty()) {
        nFft = inputLen;
    } else {
        nFft = n_arg[0];
    }
    TORCH_CHECK(nFft > 0, "n_fft must be positive");
    TORCH_CHECK(nFft % 2 == 0, "RFFT1D kernel requires even n_fft, got ", nFft);

    int64_t outputLen = nFft / 2 + 1;
    int64_t outputTotal = outputLen * 2;

    // Compute batch size (product of all dims except last)
    auto inputSizes = input.sizes();
    int64_t batchSize = 1;
    for (int64_t i = 0; i < static_cast<int64_t>(inputSizes.size()) - 1; ++i) {
        batchSize *= inputSizes[i];
    }

    // Flatten to 2D
    auto x2d = input.reshape({batchSize, inputLen}).contiguous();

    // Create padded input: (batchSize, nFft)
    at::Tensor xPadded;
    if (inputLen < nFft) {
        xPadded = at::zeros({batchSize, nFft}, at::kFloat);
        xPadded.slice(1, 0, inputLen).copy_(x2d);
    } else if (inputLen > nFft) {
        xPadded = x2d.slice(1, 0, nFft).contiguous();
    } else {
        xPadded = x2d;
    }

    // Pre-compute base angles: angles[n] = 2 * pi * n / nFft for n = 0..nFft-1
    at::Tensor angles = at::empty({nFft}, at::kFloat);
    float *anglesPtr = angles.data_ptr<float>();
    float scale = static_cast<float>(2.0 * M_PI / static_cast<double>(nFft));
    for (int64_t n = 0; n < nFft; ++n) {
        anglesPtr[n] = scale * static_cast<float>(n);
    }

    // Norm scale factor
    float normScale;
    if (norm == 1) {
        normScale = 1.0f / static_cast<float>(nFft);  // backward: 1/n
    } else if (norm == 2) {
        normScale = 1.0f;  // forward: 1
    } else {
        normScale = 1.0f / std::sqrt(static_cast<float>(nFft));  // ortho: 1/sqrt(n)
    }

    // Allocate output
    at::Tensor yOut = at::empty({batchSize, outputTotal}, at::kFloat);

    // Get platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());

    // Block scheduling
    int64_t usedCoreNum = std::min<int64_t>(coreNum, std::max<int64_t>(1, batchSize));

    // All params must be left-values for EXEC_KERNEL_CMD
    int32_t batchSizeLv = static_cast<int32_t>(batchSize);
    int32_t inputLenLv = static_cast<int32_t>(inputLen);
    int32_t nFftLv = static_cast<int32_t>(nFft);
    int32_t outputTotalLv = static_cast<int32_t>(outputTotal);
    float normScaleLv = normScale;
    uint32_t blockDimLv = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(rfft1d, blockDimLv,
                    xPadded, angles, yOut,
                    batchSizeLv, inputLenLv, nFftLv, outputTotalLv, normScaleLv);

    // Reshape output to match input batch dims
    std::vector<int64_t> outShape(inputSizes.begin(), inputSizes.end() - 1);
    outShape.push_back(outputTotal);
    return yOut.reshape(outShape);
}

}  // namespace ascend_kernel
