// AscendC RFFT1D kernel — 1D Real-to-Complex FFT via pre-computed DFT coefficients.
//
// Host pre-computes the DFT coefficient matrix: dftWeights[outputTotal][nFft].
// Kernel performs batched matmul-like operations: for each output row k,
// computes dot(x, dftWeights[k]).
//
// Float32 only (reference model always casts to float32).

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

__aicore__ inline void LoadGmToUbFloat(
    AscendC::LocalTensor<float> &dst,
    const AscendC::GlobalTensor<float> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<float> padParams{true, 0, 0, 0.0f};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

// =========================================================================
// RFFT1D Kernel
// =========================================================================

class Rfft1DKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR xPadded,
        GM_ADDR dftWeights,
        GM_ADDR yOut,
        int32_t batchSize,
        int32_t nFft,
        int32_t dftRow,    // number of rows per sequence
        int32_t dftCol,    // nFft
        float normScale)
    {
        batchSize_ = batchSize;
        nFft_ = nFft;
        dftRow_ = dftRow;
        dftCol_ = dftCol;
        normScale_ = normScale;

        uint64_t xStride = static_cast<uint64_t>(nFft_);
        xPaddedGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(xPadded),
                                    static_cast<uint64_t>(batchSize_) * xStride);
        dftGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(dftWeights),
                                static_cast<uint64_t>(dftRow_) * dftCol_);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(yOut),
                             static_cast<uint64_t>(batchSize_) * dftRow_);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, dftCol_ * sizeof(float));
            pipe.InitBuffer(wInQueue_, BUFFER_NUM, dftCol_ * sizeof(float));
            pipe.InitBuffer(prodBuf_, dftCol_ * sizeof(float));
            pipe.InitBuffer(reduceBuf_, dftCol_ * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int32_t tasksPerCore = CeilDivI32(batchSize_, AscendC::GetBlockNum());

            for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                int32_t bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= batchSize_) { continue; }
                ProcessSequence(bx);
            }
        }
    }

private:
    __aicore__ inline void CopyInX(int32_t bx)
    {
        xLocal_ = xInQueue_.AllocTensor<float>();
        LoadGmToUbFloat(xLocal_, xPaddedGM_[static_cast<uint64_t>(bx) * nFft_],
                        static_cast<uint32_t>(nFft_));
        xInQueue_.EnQue(xLocal_);
    }

    __aicore__ inline void CopyInWeights(int32_t rowIdx)
    {
        wLocal_ = wInQueue_.AllocTensor<float>();
        LoadGmToUbFloat(wLocal_, dftGM_[static_cast<uint64_t>(rowIdx) * dftCol_],
                        static_cast<uint32_t>(dftCol_));
        wInQueue_.EnQue(wLocal_);
    }

    __aicore__ inline void ProcessSequence(int32_t bx)
    {
        prodLocal_ = prodBuf_.Get<float>();
        reduceLocal_ = reduceBuf_.Get<float>();

        // Load input once per sequence
        CopyInX(bx);

        for (int32_t k = 0; k < dftRow_; ++k) {
            // Load DFT weight row for output k
            CopyInWeights(k);

            xLocal_ = xInQueue_.DeQue<float>();
            wLocal_ = wInQueue_.DeQue<float>();

            // dot product: y = Σ(x * w) * normScale
            AscendC::Mul(prodLocal_, xLocal_, wLocal_, dftCol_);
            AscendC::ReduceSum<float>(reduceLocal_, prodLocal_, reduceLocal_,
                                       static_cast<uint32_t>(dftCol_));

            float val = reduceLocal_.GetValue(0) * normScale_;

            xInQueue_.FreeTensor(xLocal_);
            wInQueue_.FreeTensor(wLocal_);
        }
    }

private:
    int32_t batchSize_ = 0;
    int32_t nFft_ = 0;
    int32_t dftRow_ = 0;
    int32_t dftCol_ = 0;
    float normScale_ = 1.0f;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<float> xPaddedGM_;
    AscendC::GlobalTensor<float> dftGM_;
    AscendC::GlobalTensor<float> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> wInQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> prodBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;

    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> wLocal_;
    AscendC::LocalTensor<float> prodLocal_;
    AscendC::LocalTensor<float> reduceLocal_;
};

// =========================================================================
// Kernel entry point
// =========================================================================

extern "C" __global__ __aicore__ void rfft1d(
    GM_ADDR xPadded,
    GM_ADDR dftWeights,
    GM_ADDR yOut,
    int32_t batchSize,
    int32_t nFft,
    int32_t dftRow,
    int32_t dftCol,
    float normScale)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);
    Rfft1DKernel kernel;
    kernel.Init(xPadded, dftWeights, yOut, batchSize, nFft, dftRow, dftCol, normScale);
    kernel.Process();
}
