// RFFT1D op_host — accepts pre-computed DFT weights, launches kernel

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_rfft1d.h"

namespace ascend_kernel {

at::Tensor rfft1d(
    const at::Tensor &xPadded,
    const at::Tensor &dftWeights,
    int64_t nFft,
    int64_t outputTotal,
    double normScaleArg)
{
    // Input validation
    TORCH_CHECK(xPadded.dtype() == at::kFloat, "xPadded must be float32");
    TORCH_CHECK(dftWeights.dtype() == at::kFloat, "dftWeights must be float32");

    int64_t batchSize = xPadded.size(0);
    int64_t dftCol = xPadded.size(1);
    int64_t dftRow = outputTotal;

    TORCH_CHECK(dftWeights.size(0) == dftRow,
        "dftWeights dim 0 must match outputTotal: ", dftWeights.size(0), " vs ", dftRow);
    TORCH_CHECK(dftWeights.size(1) == dftCol,
        "dftWeights dim 1 must match nFft: ", dftWeights.size(1), " vs ", dftCol);

    // Allocate output
    at::Tensor yOut = at::empty({batchSize, outputTotal}, at::kFloat);

    // Get platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    int64_t usedCoreNum = std::min<int64_t>(coreNum, std::max<int64_t>(1, batchSize));

    // All params must be left-values for EXEC_KERNEL_CMD
    int32_t batchSizeLv = static_cast<int32_t>(batchSize);
    int32_t nFftLv = static_cast<int32_t>(nFft);
    int32_t dftRowLv = static_cast<int32_t>(dftRow);
    int32_t dftColLv = static_cast<int32_t>(dftCol);
    float normScaleLv = static_cast<float>(normScaleArg);
    uint32_t blockDimLv = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(rfft1d, blockDimLv,
                    xPadded, dftWeights, yOut,
                    batchSizeLv, nFftLv, dftRowLv, dftColLv, normScaleLv);

    return yOut;
}

}  // namespace ascend_kernel
