// AscendC RFFT1D kernel — 1D Real-to-Complex FFT via pre-computed DFT coefficients.
//
// Host pre-computes the DFT coefficient matrix: dftWeights[outputTotal][nFft].
// Kernel computes: for each output row k, y[k] = dot(x, dftWeights[k]) * normScale.
// Uses vector Mul + scalar accumulation to avoid ReduceSum linker issues.
//
// Float32 only (reference model always casts to float32).

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// =========================================================================
// RFFT1D Kernel
// =========================================================================

template <typename T>
class Rfft1DKernel {
public:
    __aicore__ inline Rfft1DKernel() {}

    __aicore__ inline void Init(
        GM_ADDR xPadded,
        GM_ADDR dftWeights,
        GM_ADDR yOut,
        int32_t batchSize,
        int32_t nFft,
        int32_t dftRow,
        int32_t dftCol,
        float normScale)
    {
        batchSize_ = batchSize;
        nFft_ = nFft;
        dftRow_ = dftRow;
        dftCol_ = dftCol;
        normScale_ = normScale;

        uint64_t xStride = static_cast<uint64_t>(nFft_);
        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(xPadded),
                             static_cast<uint64_t>(batchSize_) * xStride);
        wGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(dftWeights),
                             static_cast<uint64_t>(dftRow_) * dftCol_);
        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(yOut),
                             static_cast<uint64_t>(batchSize_) * dftRow_);

        uint32_t alignN = Align32B(dftCol_);
        pipe_.InitBuffer(inQueueX_, BUFFER_NUM, alignN * sizeof(T));
        pipe_.InitBuffer(inQueueW_, BUFFER_NUM, alignN * sizeof(T));
        pipe_.InitBuffer(prodBuf_, alignN * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        int32_t coreIdx = AscendC::GetBlockIdx();
        int32_t tasksPerCore = CeilDivI32(batchSize_, AscendC::GetBlockNum());

        for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
            int32_t bx = coreIdx * tasksPerCore + localIdx;
            if (bx >= batchSize_) { continue; }
            ProcessSequence(bx);
        }
    }

private:
    __aicore__ inline uint32_t Align32B(uint32_t len) const
    {
        const uint32_t alignSize = 32 / sizeof(T);
        return (len + alignSize - 1) / alignSize * alignSize;
    }

    __aicore__ inline int32_t CeilDivI32(int32_t a, int32_t b) const
    {
        if (b == 0) { return 0; }
        return (a + b - 1) / b;
    }

    __aicore__ inline void ProcessSequence(int32_t bx)
    {
        uint32_t nFftU = static_cast<uint32_t>(nFft_);
        uint32_t dftColU = static_cast<uint32_t>(dftCol_);

        // Load x once per sequence
        AscendC::LocalTensor<T> xLocal = inQueueX_.AllocTensor<T>();
        AscendC::DataCopyPadParams copyPadParams;
        AscendC::DataCopyPad(
            xLocal, xGm_[static_cast<uint64_t>(bx) * nFft_],
            {1, static_cast<uint16_t>(dftColU * sizeof(T)), 0, 0},
            copyPadParams);
        inQueueX_.EnQue(xLocal);

        // Process each output row (DFT dot product)
        for (int32_t k = 0; k < dftRow_; ++k) {
            // Load weight row
            AscendC::LocalTensor<T> wLocal = inQueueW_.AllocTensor<T>();
            AscendC::DataCopyPad(
                wLocal, wGm_[static_cast<uint64_t>(k) * dftCol_],
                {1, static_cast<uint16_t>(dftColU * sizeof(T)), 0, 0},
                copyPadParams);
            inQueueW_.EnQue(wLocal);

            // DeQue x and w
            AscendC::LocalTensor<T> xDeq = inQueueX_.DeQue<T>();
            AscendC::LocalTensor<T> wDeq = inQueueW_.DeQue<T>();

            // prod = x * w (element-wise, vector)
            AscendC::LocalTensor<T> prodLocal = prodBuf_.Get<T>();
            AscendC::Mul(prodLocal, xDeq, wDeq, dftColU);

            // Accumulate sum via scalar
            float acc = 0.0f;
            for (uint32_t i = 0; i < dftColU; ++i) {
                if constexpr (sizeof(T) == sizeof(float)) {
                    acc += prodLocal.GetValue(i);
                } else {
                    acc += static_cast<float>(prodLocal.GetValue(i));
                }
            }

            float val = acc * normScale_;
            AscendC::LocalTensor<T> tmpL = prodBuf_.Get<T>();
            AscendC::Duplicate<T>(tmpL, static_cast<T>(val), 1);
            inQueueX_.FreeTensor(xDeq);
            inQueueW_.FreeTensor(wDeq);

            // Write output
            AscendC::DataCopyPad(
                yGm_[static_cast<uint64_t>(bx) * dftRow_ + k], tmpL,
                {1, static_cast<uint16_t>(sizeof(T)), 0, 0});
