// RFFT1D Kernel
// =========================================================================

class Rfft1DKernel {
public:
    __aicore__ inline Rfft1DKernel() {}

    __aicore__ inline void Init(
        GM_ADDR xPadded,
        GM_ADDR dftWeights,
        GM_ADDR yOut,
        int32_t batchSize,
        int32_t nFft,
        int32_t dftRow,
        int32_t dftCol,
        float normScale)
    {
        batchSize_ = batchSize;
        nFft_ = nFft;
        dftRow_ = dftRow;
        dftCol_ = dftCol;
        normScale_ = normScale;

        uint64_t xStride = static_cast<uint64_t>(nFft_);
        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(xPadded),
                             static_cast<uint64_t>(batchSize_) * xStride);
        wGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(dftWeights),
                             static_cast<uint64_t>(dftRow_) * dftCol_);
        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(yOut),
                             static_cast<uint64_t>(batchSize_) * dftRow_);

        uint32_t tileBytes = TILE_N * sizeof(float);
        pipe_.InitBuffer(inQueueX_, BUFFER_NUM, tileBytes);
        pipe_.InitBuffer(inQueueW_, BUFFER_NUM, tileBytes);
        pipe_.InitBuffer(prodBuf_, tileBytes);
    }

    __aicore__ inline void Process()
    {
        int32_t coreIdx = AscendC::GetBlockIdx();
        int32_t tasksPerCore = CeilDivI32(batchSize_, AscendC::GetBlockNum());

        for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
            int32_t bx = coreIdx * tasksPerCore + localIdx;
            if (bx >= batchSize_) { continue; }
            ProcessSequence(bx);
        }
    }

