    int32_t nFft_ = 0;
    int32_t dftRow_ = 0;
    int32_t dftCol_ = 0;
    float normScale_ = 1.0f;

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<float> xGm_;
    AscendC::GlobalTensor<float> wGm_;
