#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t TILE_N = 512;

class Rfft1DKernel {
public:
    __aicore__ inline Rfft1DKernel() {}

    __aicore__ inline void Init(
        GM_ADDR xPadded,
        GM_ADDR dftWeights,
        GM_ADDR yOut,
        int32_t batchSize,
        int32_t nFft,
        int32_t dftRow,
        int32_t dftCol,
        float normScale)
    {
        batchSize_ = batchSize;
        nFft_ = nFft;
        dftRow_ = dftRow;
        dftCol_ = dftCol;
        normScale_ = normScale;

        uint64_t xStride = static_cast<uint64_t>(nFft_);
        uint64_t dftStride = static_cast<uint64_t>(dftCol_);
        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(xPadded),
                             static_cast<uint64_t>(batchSize_) * xStride);
        wGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(dftWeights),
                             static_cast<uint64_t>(dftRow_) * dftStride);
        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(yOut),
                             static_cast<uint64_t>(batchSize_) * dftRow_);

        uint32_t tileBytes = static_cast<uint32_t>(TILE_N * sizeof(float));
        pipe_.InitBuffer(inQueueX_, BUFFER_NUM, tileBytes);
        pipe_.InitBuffer(inQueueW_, BUFFER_NUM, tileBytes);
        pipe_.InitBuffer(prodBuf_, tileBytes);
    }

    __aicore__ inline void Process()
    {
        int64_t subBlockIdx = AscendC::GetSubBlockIdx();
        int64_t subBlockNum = AscendC::GetSubBlockNum();
        // sub-block 0 gets even tasks, sub-block 1 gets odd tasks
        for (int32_t bx = static_cast<int32_t>(subBlockIdx); bx < batchSize_;
             bx += static_cast<int32_t>(subBlockNum)) {
            ProcessSequence(bx);
        }
    }

private:
    __aicore__ inline void ProcessSequence(int32_t bx)
    {
        uint32_t nFftU = static_cast<uint32_t>(nFft_);
        uint32_t dftColU = static_cast<uint32_t>(dftCol_);

        for (int32_t k = 0; k < dftRow_; ++k) {
            float dotSum = 0.0f;
            int32_t tileNum = (dftCol_ + TILE_N - 1) / TILE_N;

            for (int32_t t = 0; t < tileNum; ++t) {
                int32_t nStart = t * TILE_N;
                int32_t validN = (nStart + TILE_N <= dftCol_) ? TILE_N : (dftCol_ - nStart);
                uint32_t validNU = static_cast<uint32_t>(validN);

                // CopyIn X tile
                AscendC::LocalTensor<float> xLocal = inQueueX_.AllocTensor<float>();
                AscendC::DataCopyPadParams padParams;
                AscendC::DataCopyPad(
                    xLocal, xGm_[static_cast<uint64_t>(bx) * nFftU + nStart],
                    {1, static_cast<uint16_t>(validNU * sizeof(float)), 0, 0},
                    padParams);
                inQueueX_.EnQue(xLocal);

                // CopyIn W tile
                AscendC::LocalTensor<float> wLocal = inQueueW_.AllocTensor<float>();
                AscendC::DataCopyPad(
                    wLocal, wGm_[static_cast<uint64_t>(k) * dftColU + nStart],
                    {1, static_cast<uint16_t>(validNU * sizeof(float)), 0, 0},
                    padParams);
                inQueueW_.EnQue(wLocal);

                // DeQue
                AscendC::LocalTensor<float> xDeq = inQueueX_.DeQue<float>();
                AscendC::LocalTensor<float> wDeq = inQueueW_.DeQue<float>();

                // prod = x * w (vector element-wise)
                AscendC::LocalTensor<float> prodLocal = prodBuf_.Get<float>();
                AscendC::Mul(prodLocal, xDeq, wDeq, validNU);

                // Scalar summation
                float tileSum = 0.0f;
                for (uint32_t i = 0; i < validNU; ++i) {
                    tileSum += prodLocal.GetValue(i);
                }
                dotSum += tileSum;

                inQueueX_.FreeTensor(xDeq);
                inQueueW_.FreeTensor(wDeq);
            }

            float val = dotSum * normScale_;

            // Write single float to output
            AscendC::LocalTensor<float> tmpL = prodBuf_.Get<float>();
            tmpL.SetValue(0, val);
            AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
            AscendC::DataCopyPad(yGm_[static_cast<uint64_t>(bx) * dftRow_ + k], tmpL, copyParams);
        }
    }

private:
    int32_t batchSize_ = 0;
    int32_t nFft_ = 0;
    int32_t dftRow_ = 0;
    int32_t dftCol_ = 0;
    float normScale_ = 1.0f;

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<float> xGm_;
    AscendC::GlobalTensor<float> wGm_;
    AscendC::GlobalTensor<float> yGm_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueW_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> prodBuf_;
};

