            dot *= normScale_;
            AscendC::LocalTensor<T> tmp = pB_.Get<T>();
            tmp.SetValue(0, static_cast<T>(dot));
            AscendC::DataCopyExtParams cpO{1, static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
            AscendC::DataCopyPad(yGm_[static_cast<uint64_t>(bx) * dftRow_ + k], tmp, cpO);
        }
    }

    int32_t batchSize_=0, nFft_=0, dftRow_=0, dftCol_=0;
    float normScale_=1.0f;
    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<T> xGm_, wGm_, yGm_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inX_, inW_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> pB_;
};

