// AscendC RFFT1D kernel — batched DFT via pre-computed coefficient matrix.
// Uses TQue for GM<->UB transfers, TBuf for intermediate computation.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t TILE_N = 512;

template <typename T>
class Rfft1DKernel {
public:
    __aicore__ inline Rfft1DKernel() {}

    __aicore__ inline void Init(GM_ADDR xP, GM_ADDR dW, GM_ADDR yO,
        int32_t bS, int32_t nF, int32_t dR, int32_t dC, float nS)
    {
        batchSize_ = bS; nFft_ = nF; dftRow_ = dR; dftCol_ = dC; normScale_ = nS;
        uint64_t xs = static_cast<uint64_t>(nFft_);
        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(xP), static_cast<uint64_t>(bS) * xs);
        wGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(dW), static_cast<uint64_t>(dR) * dC);
        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(yO), static_cast<uint64_t>(bS) * dR);
        uint32_t tB = static_cast<uint32_t>(TILE_N * sizeof(T));
        pipe_.InitBuffer(inX_, BUFFER_NUM, tB);
        pipe_.InitBuffer(inW_, BUFFER_NUM, tB);
        pipe_.InitBuffer(pB_, tB);
    }

    __aicore__ inline void Process()
    {
        int64_t cIdx = AscendC::GetBlockIdx();
        int32_t nT = (batchSize_ + static_cast<int32_t>(AscendC::GetBlockNum()) - 1) /
                     static_cast<int32_t>(AscendC::GetBlockNum());
        for (int32_t ti = 0; ti < nT; ++ti) {
            int32_t bx = static_cast<int32_t>(cIdx) * nT + ti;
            if (bx >= batchSize_) continue;
            ProcessSeq(bx);
        }
    }

private:
    __aicore__ inline void ProcessSeq(int32_t bx)
    {
        uint32_t dCU = static_cast<uint32_t>(dftCol_);
        uint32_t nFU = static_cast<uint32_t>(nFft_);
        int32_t tN = (dftCol_ + TILE_N - 1) / TILE_N;

        for (int32_t k = 0; k < dftRow_; ++k) {
            float dot = 0.0f;

            for (int32_t ti = 0; ti < tN; ++ti) {
                int32_t nS = ti * TILE_N;
                int32_t vN = (nS + TILE_N <= dftCol_) ? TILE_N : (dftCol_ - nS);
                uint32_t vNU = static_cast<uint32_t>(vN);
                uint32_t vBytes = vNU * static_cast<uint32_t>(sizeof(T));

                // CopyIn X via TQue
                AscendC::LocalTensor<T> xL = inX_.AllocTensor<T>();
                AscendC::DataCopyExtParams cp{1, vBytes, 0, 0, 0};
                AscendC::DataCopyPadExtParams<T> pp{false, 0, 0, static_cast<T>(0)};
                AscendC::DataCopyPad(xL, xGm_[static_cast<uint64_t>(bx) * nFU + nS], cp, pp);
                inX_.EnQue(xL);

                // CopyIn W via TQue
                AscendC::LocalTensor<T> wL = inW_.AllocTensor<T>();
                AscendC::DataCopyPad(wL, wGm_[static_cast<uint64_t>(k) * dCU + nS], cp, pp);
                inW_.EnQue(wL);

                // DeQue both
                AscendC::LocalTensor<T> xD = inX_.DeQue<T>();
                AscendC::LocalTensor<T> wD = inW_.DeQue<T>();

                // Vector mul on TBuf
                AscendC::LocalTensor<T> pL = pB_.Get<T>();
                AscendC::Mul(pL, xD, wD, vNU);

                // Scalar accumulation
                float tS = 0.0f;
                for (int32_t i = 0; i < vN; ++i) {
                    tS += static_cast<float>(pL.GetValue(i));
                }
                dot += tS;

                inX_.FreeTensor(xD);
                inW_.FreeTensor(wD);
            }

            // Write output: single element via DataCopyPad
            dot *= normScale_;
            AscendC::LocalTensor<T> tmp = pB_.Get<T>();
            tmp.SetValue(0, static_cast<T>(dot));
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::DataCopyExtParams cpO{1, static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
            AscendC::DataCopyPad(yGm_[static_cast<uint64_t>(bx) * dftRow_ + k], tmp, cpO);
        }
    }

    int32_t batchSize_=0, nFft_=0, dftRow_=0, dftCol_=0;
    float normScale_=1.0f;
    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<T> xGm_, wGm_, yGm_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inX_, inW_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> pB_;
};

extern "C" __global__ __aicore__ void rfft1d(
    GM_ADDR xP, GM_ADDR dW, GM_ADDR yO,
    int32_t bS, int32_t nF, int32_t dR, int32_t dC, float nS)
{
    Rfft1DKernel<float> k;
    k.Init(xP, dW, yO, bS, nF, dR, dC, nS);
    k.Process();
}
